    if (arr[i] % 2 === 0) continue;

    sum += arr[i];

    // 合計が 50 を超ったら即座に止める
    if (sum > 50) break; 

    console.log(`現在の合計: ${sum}`);
  }
  return sum;
}

findOddSum([1, 2, 3, 100, 500]); // break 実行して 50 を超える前に停止
```

