  debug: true,
  apiVersion: 1.2,
  features: ['dashboard', 'analytics'] as const // Const assertions など高度な使い方を混ぜるとより限定厳しくできる

  // ※注意: これは関数型または引数の型など、他の箇所から参照しない限りは冗長になることがある
